第六题（12分）
程序i16.c如下：
```
#include <stdio.h>
#include <fcntl.h>
#include <unistd.h>
#include <ctype.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <sys/wait.h>
#include "csapp.h"
int main(int argc, char **argv)
{
  int fd1, fd2;
  char *cs;
  struct stat stat;
  int sz, i;
  fd1 = Open(argv[1], O_RDWR, S_IRUSR | S_IWUSR);
  Fstat(fd1, &stat);
  sz = stat.st_size;
  fd2 = Open(argv[2], O_RDWR | O_TRUNC | O_CREAT, \
             S_IRUSR | S_IWUSR);
  cs = (char *)Mmap(NULL, sz, PROT_READ | PROT_WRITE, \
                    X, fd1, 0);
  if (Fork()) {
    Wait(&i);
    Write(fd2, cs, sz);
  } else {
    for (i = 0; i < sz; i++) {
      if (islower(cs[i]))
        cs[i] = (char) toupper(cs[i]);
      else if (isupper(cs[i]))
        cs[i] = (char) tolower(cs[i]);
    }
       Y         ;
  }
  Munmap(cs, sz);
  Close(fd1);
  Close(fd2);
}
```
1、假定t1内容为ICSexam，根据X/Y处的内容，判断执行./i16 t1 t2之后
的结果：（均为单选题）
1.1、X为MAP_PRIVATE，Y为空时，结果为（    ）
A. t1为ICSexam，t2为ICSexam
B. t1为ICSexam，t2为icsEXAM
C. t1为icsEXAM，t2为icsEXAM
D. t1为icsEXAM，t2为ICSexam
1.2、X为MAP_SHARED时，Y为空时，结果为（    ）
A. t1为ICSexam，t2为ICSexam
B. t1为ICSexam，t2为icsEXAM
C. t1为icsEXAM，t2为icsEXAM
D. t1为icsEXAM，t2为ICSexam
1.3、X处的内容为MAP_PRIVATE，Y为Write(fd2, cs, sz)时，t2的
结果为（    ）
A. t2为ICSexam
B. t2为icsEXAM
C. t2为icsEXAMICSexam
D. t2为icsEXAMicsEXAM
1.4、X处的内容为MAP_SHARED，Y为Write(fd2, cs, sz)时，t2的结
果为（    ）
A. t2为ICSexam
B. t2为icsEXAM
C. t2为icsEXAMICSexam
D. t2为icsEXAMicsEXAM


